<script setup>import {ref,computed,onMounted} from 'vue';import {useData} from '../stores/data';import Notice from '../components/Notice.vue';const store=useData(),student=ref(''),course=ref(''),rosterCourse=ref(''),enrollments=ref([]),message=ref(''),error=ref(''),busy=ref(false);const roster=computed(()=>enrollments.value.filter(e=>e.course?._id===rosterCourse.value));async function load(){await store.refresh();enrollments.value=await store.request('/enrollments')}onMounted(()=>load().catch(e=>error.value=e.message));async function add(){busy.value=true;error.value='';message.value='';try{await store.request('/enrollments',{method:'POST',body:JSON.stringify({student:student.value,course:course.value})});await load();message.value='Enrollment added successfully'}catch(e){error.value=e.message}finally{busy.value=false}}async function remove(e){if(!confirm('Remove this enrollment?'))return;try{await store.request('/enrollments/'+e._id,{method:'DELETE'});await load();message.value='Enrollment removed';error.value=''}catch(err){error.value=err.message}}</script><template><div class="eyebrow">COURSE REGISTRATION</div><h1>Enrollments</h1><p class="subtitle">Connect students to courses and explore class rosters.</p><div class="stats"><div class="stat"><span>Total enrollments</span><strong>{{enrollments.length}}</strong></div></div><div class="two-col"><section class="panel"><div class="panel-heading"><h2>New enrollment</h2></div><form @submit.prevent="add" class="form"><label>Student<select v-model="student" required><option value="" disabled>Select a student</option><option v-for="s in store.students" :key="s._id" :value="s._id">{{s.name}} ({{s.id}})</option></select></label><label>Course<select v-model="course" required><option value="" disabled>Select a course</option><option v-for="c in store.courses" :key="c._id" :value="c._id">{{c.id}} — {{c.name}}</option></select></label><button class="primary" :disabled="busy||!store.students.length||!store.courses.length">{{busy?'Enrolling…':'+ Enroll student'}}</button></form><Notice :message="error" type="error"/><Notice :message="message"/></section><section class="panel"><div class="panel-heading"><h2>Course roster</h2></div><label class="select-label">View course<select v-model="rosterCourse"><option value="">Select a course to view roster</option><option v-for="c in store.courses" :key="c._id" :value="c._id">{{c.id}} — {{c.name}}</option></select></label><div v-if="!rosterCourse" class="empty">Choose a course.</div><div v-else-if="!roster.length" class="empty">No students enrolled in this course.</div><div v-for="e in roster" :key="e._id" class="record"><div class="avatar">{{e.student?.name?.charAt(0)||'?'}}</div><div class="record-body"><strong>{{e.student?.name}}</strong><span>Student ID {{e.student?.id}}</span></div><button class="danger" @click="remove(e)">Remove</button></div></section></div></template>